/* 白榆顶栏原生闪电修复 v2：不替换功能按钮，不覆盖成三个点。 */
.sully-chat-root .sully-chat-header .sully-chat-trigger{
 position:absolute!important;right:0!important;bottom:8px!important;
 z-index:5!important;visibility:visible!important;opacity:1!important;
 pointer-events:auto!important;display:flex!important;align-items:center!important;
 justify-content:center!important;color:var(--wy-ink)!important;
 background:transparent!important;box-shadow:none!important;
 transform:none!important;
}
.sully-chat-root .sully-chat-header .sully-chat-trigger svg{
 visibility:visible!important;display:block!important;opacity:1!important;
 color:inherit!important;width:20px!important;height:20px!important;
}
.sully-chat-root .sully-chat-header .sully-chat-trigger::before,
.sully-chat-root .sully-chat-header .sully-chat-trigger::after{
 content:none!important;display:none!important;
}
.sully-chat-root .sully-chat-header button[aria-label="电话"],
.sully-chat-root .sully-chat-header button[aria-label="群聊记忆规则"]{
 position:absolute!important;right:40px!important;bottom:8px!important;
 z-index:4!important;display:flex!important;align-items:center!important;
 justify-content:center!important;transform:none!important;
}
.sully-chat-root .sully-chat-header:not(:has(.sully-chat-trigger)) button[aria-label="电话"],
.sully-chat-root .sully-chat-header:not(:has(.sully-chat-trigger)) button[aria-label="群聊记忆规则"]{
 right:0!important;
}
.sully-chat-root .sully-chat-header .sully-chat-back{
 position:absolute!important;left:0!important;bottom:8px!important;
 z-index:5!important;transform:none!important;
}
